<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';zorunlu_rol('admin','yonetici');
$toyTurleri=toy_turleri();$kategoriler=toy_kategorileri();$sezonlar=$pdo->query("SELECT * FROM sezonlar WHERE durum='aktif' ORDER BY sezon_adi DESC")->fetchAll();$id=(int)($_GET['id']??$_POST['toy_id']??0);$islem=$_GET['islem']??'';
function toy_form_ayarlari($tur,$post){$ayar=[];$set=$tur==='sabit_puta'?max(1,min(30,(int)($post['set_sayisi']??1))):null;if($tur==='uzaklasan_puta'){$ayar['mesafeler']=array_values(array_unique(array_filter(array_map('intval',$post['mesafeler']??[]))));if(!$ayar['mesafeler'])throw new RuntimeException('Uzaklaşan Puta için en az bir mesafe seçin.');}if($tur==='uc_boyutlu_hedef'){$izinli=['Kuş','Tavşan','Tilki','Geyik','Domuz','Ayı'];$ayar['hedefler']=array_values(array_intersect($izinli,$post['hedefler']??[]));if(!$ayar['hedefler'])throw new RuntimeException('3 Boyutlu Hedef için en az bir hedef seçin.');}return [$set,$ayar];}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if(!csrf_check($_POST['csrf']??''))throw new RuntimeException('Güvenlik doğrulaması başarısız.');$postIslem=$_POST['islem']??'';
  if($postIslem==='toy_sil'){if(!$id)throw new RuntimeException('Yarışma bulunamadı.');$pdo->prepare('DELETE FROM toylar WHERE id=?')->execute([$id]);flash_set('basari','Yarışma silindi.');}
  else{$ad=trim($_POST['toy_adi']??'');$turler=array_values(array_intersect(array_keys($toyTurleri),$_POST['yarisma_turleri']??[]));$secilenKategoriler=array_values(array_intersect(array_keys($kategoriler),$_POST['kategoriler']??[]));$sezonId=(int)($_POST['sezon_id']??0);$sporcuIds=array_values(array_unique(array_filter(array_map('intval',$_POST['sporcu_ids']??[]))));
   if($ad===''||!$turler||!$secilenKategoriler||!$sezonId)throw new RuntimeException('Yarışma adı, en az bir yarış türü, kategori ve sezon seçin.');if(!$sporcuIds)throw new RuntimeException('En az bir sporcu seçin.');
   $yer=implode(',',array_fill(0,count($sporcuIds),'?'));$st=$pdo->prepare("SELECT id,kategori FROM sporcular WHERE id IN ($yer)");$st->execute($sporcuIds);$sporcuKategori=[];foreach($st->fetchAll() as $s)$sporcuKategori[(int)$s['id']]=$s['kategori'];if(count($sporcuKategori)!==count($sporcuIds))throw new RuntimeException('Seçilen sporculardan biri bulunamadı.');
   foreach($secilenKategoriler as $kategori){if(!array_filter($sporcuKategori,fn($kat)=>$kat===$kategori))throw new RuntimeException(($kategoriler[$kategori]??$kategori).' kategorisi için en az bir sporcu seçin.');}
   if($postIslem==='toy_guncelle'){$tur=$turler[0];$kategori=$secilenKategoriler[0];[$set,$ayar]=toy_form_ayarlari($tur,$_POST);$pdo->prepare('UPDATE toylar SET toy_adi=?,yarisma_turu=?,kategori=?,sezon_id=?,set_sayisi=?,ayarlar_json=?,aciklama=? WHERE id=?')->execute([$ad,$tur,$kategori,$sezonId,$set,json_encode($ayar,JSON_UNESCAPED_UNICODE),trim($_POST['aciklama']??''),$id]);$pdo->prepare('DELETE FROM toy_katilimcilari WHERE toy_id=?')->execute([$id]);$pdo->prepare('DELETE FROM toy_puanlari WHERE toy_id=?')->execute([$id]);$toyler=[['id'=>$id,'kategori'=>$kategori]];$mesaj='Yarışma güncellendi; önceki puanlar sıfırlandı.';}
   else{$ekle=$pdo->prepare('INSERT INTO toylar(toy_adi,yarisma_turu,kategori,sezon_id,set_sayisi,ayarlar_json,aciklama) VALUES(?,?,?,?,?,?,?)');$toyler=[];foreach($turler as $tur){[$set,$ayar]=toy_form_ayarlari($tur,$_POST);foreach($secilenKategoriler as $kategori){$ekle->execute([$ad,$tur,$kategori,$sezonId,$set,json_encode($ayar,JSON_UNESCAPED_UNICODE),trim($_POST['aciklama']??'')]);$toyler[]=['id'=>(int)$pdo->lastInsertId(),'kategori'=>$kategori];}}$mesaj=count($toyler).' yarışma oluşturuldu.';}
   $katilimci=$pdo->prepare('INSERT INTO toy_katilimcilari(toy_id,sporcu_id) VALUES(?,?)');foreach($toyler as $toy)foreach($sporcuKategori as $sporcuId=>$kategori)if($kategori===$toy['kategori'])$katilimci->execute([$toy['id'],$sporcuId]);flash_set('basari',$mesaj);
  }
 }catch(Throwable $e){flash_set('hata',$e->getMessage());}redirect(BASE_URL.'/admin/toylar.php');
}
$secili=null;$seciliSporcular=[];if($islem==='duzenle'&&$id){$st=$pdo->prepare('SELECT * FROM toylar WHERE id=?');$st->execute([$id]);$secili=$st->fetch();if(!$secili){flash_set('hata','Yarışma bulunamadı.');redirect(BASE_URL.'/admin/toylar.php');}$st=$pdo->prepare('SELECT sporcu_id FROM toy_katilimcilari WHERE toy_id=?');$st->execute([$id]);$seciliSporcular=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));}
$sporcular=$pdo->query('SELECT id,ad,soyad,kategori,takim_id FROM sporcular ORDER BY kategori,ad,soyad')->fetchAll();$liste=$pdo->query("SELECT t.*,s.sezon_adi,COUNT(k.id) katilimci FROM toylar t LEFT JOIN sezonlar s ON s.id=t.sezon_id LEFT JOIN toy_katilimcilari k ON k.toy_id=t.id GROUP BY t.id ORDER BY t.toy_adi,t.created_at DESC")->fetchAll();$seciliAyar=$secili?toy_ayarlarini_al($secili):[];$gruplu=[];foreach($liste as $toy)$gruplu[$toy['toy_adi'].'|'.($toy['sezon_adi']??'')][]=$toy;
ob_start();
?>
<div class="lig-sayfa-iki-kolon"><section class="card"><div class="card-head"><h2><?= $secili?'Toy Yarışını Düzenle':'Toy Oluştur' ?></h2></div><p class="muted">Bir Toy adı altında birden fazla yarış türü ve kategori birlikte oluşturulabilir.</p><form method="post" class="form" id="toyForm"><?= csrf_field() ?><input type="hidden" name="islem" value="<?= $secili?'toy_guncelle':'toy_olustur' ?>"><?php if($secili): ?><input type="hidden" name="toy_id" value="<?= (int)$secili['id'] ?>"><?php endif; ?><div class="grid-2"><label>Toy adı *<input name="toy_adi" required value="<?= e($secili['toy_adi']??'') ?>" placeholder="Örn. Bursa Toyu"></label><label>Sezon *<select name="sezon_id" required><?php foreach($sezonlar as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $secili&&(int)$secili['sezon_id']===(int)$s['id']?'selected':'' ?>><?= e($s['sezon_adi']) ?></option><?php endforeach; ?></select></label></div>
<div class="toy-secim-alani"><span class="form-label">Toy Yarışları *</span><div class="toy-check-grid toy-tur-secici"><?php foreach($toyTurleri as $anahtar=>$etiket): ?><label class="toy-secim-karti"><input type="checkbox" name="yarisma_turleri[]" value="<?= e($anahtar) ?>" <?= (!$secili||$secili['yarisma_turu']===$anahtar)?'checked':'' ?> <?= $secili&&$secili['yarisma_turu']!==$anahtar?'disabled':'' ?>><span><?= e($etiket) ?></span></label><?php endforeach; ?></div></div>
<div class="toy-secim-alani"><span class="form-label">Sporcu Kategorileri *</span><div class="toy-check-grid toy-kategori-secici"><?php foreach($kategoriler as $anahtar=>$etiket): ?><label class="toy-secim-karti"><input type="checkbox" name="kategoriler[]" value="<?= e($anahtar) ?>" <?= (!$secili||$secili['kategori']===$anahtar)?'checked':'' ?> <?= $secili&&$secili['kategori']!==$anahtar?'disabled':'' ?>><span><?= e($etiket) ?></span></label><?php endforeach; ?></div></div>
<div class="toy-ayar" data-toy-tur="sabit_puta"><label>Atış seti sayısı *<select name="set_sayisi"><?php for($i=1;$i<=15;$i++): ?><option value="<?= $i ?>" <?= (int)($secili['set_sayisi']??3)===$i?'selected':'' ?>><?= $i ?> set</option><?php endfor; ?></select></label></div><div class="toy-ayar" data-toy-tur="uzaklasan_puta"><span class="form-label">Uzaklaşan Puta atış mesafeleri *</span><div class="toy-check-grid"><?php foreach([20,30,40,50,60,70] as $metre): ?><label class="check-line"><input type="checkbox" name="mesafeler[]" value="<?= $metre ?>" <?= in_array($metre,$seciliAyar['mesafeler']??[20,30,40],true)?'checked':'' ?>> <?= $metre ?> metre</label><?php endforeach; ?></div></div><div class="toy-ayar" data-toy-tur="uc_boyutlu_hedef"><span class="form-label">3 Boyutlu Hedefler *</span><div class="toy-check-grid"><?php foreach(['Kuş','Tavşan','Tilki','Geyik','Domuz','Ayı'] as $hedef): ?><label class="check-line"><input type="checkbox" name="hedefler[]" value="<?= e($hedef) ?>" <?= in_array($hedef,$seciliAyar['hedefler']??['Kuş','Tavşan','Tilki'],true)?'checked':'' ?>> <?= e($hedef) ?></label><?php endforeach; ?></div></div><div class="toy-ayar" data-toy-tur="menzil"><p class="hint-box">Menzil için her sporcuya tek toplam puan alanı açılır.</p></div><label>Açıklama<textarea name="aciklama"><?= e($secili['aciklama']??'') ?></textarea></label>
<details class="toy-sporcu-secici" open><summary>Sporcuları Seç <span>Yalnızca işaretlenen kategorilerdeki sporcular gösterilir.</span></summary><div class="toy-sporcu-arama"><input type="search" id="toySporcuAra" placeholder="Sporcu ara…"><button type="button" class="btn btn-sm" id="toyTumunuSec">Görünenlerin tümünü seç</button><button type="button" class="btn btn-sm btn-outline" id="toyTumunuKaldir">İşaretleri kaldır</button></div><div class="toy-sporcu-listesi"><?php foreach($sporcular as $sporcu): ?><label class="toy-sporcu" data-kategori="<?= e($sporcu['kategori']) ?>" data-arama="<?= e(mb_strtolower($sporcu['ad'].' '.$sporcu['soyad'].' '.$sporcu['kategori'])) ?>"><input type="checkbox" name="sporcu_ids[]" value="<?= (int)$sporcu['id'] ?>" <?= in_array((int)$sporcu['id'],$seciliSporcular,true)?'checked':'' ?>><span><?= e($sporcu['ad'].' '.$sporcu['soyad']) ?></span><small><?= e($kategoriler[$sporcu['kategori']]??$sporcu['kategori']) ?><?= $sporcu['takim_id']?' · Takımlı':' · Bağımsız' ?></small></label><?php endforeach; ?></div></details><div class="form-actions"><button class="btn btn-primary"><?= $secili?'Güncelle':'Toy Yarışlarını Oluştur' ?></button><?php if($secili): ?><a class="btn btn-outline" href="<?= BASE_URL ?>/admin/toylar.php">Vazgeç</a><?php endif; ?></div></form></section>
<section class="card" id="toy-yarislari"><div class="card-head"><h2>Oluşturulan Toy'lar</h2><span class="badge"><?= count($liste) ?> yarış</span></div><?php foreach($gruplu as $toyGrubu): ?><div class="toy-yonetim-grubu"><h3>🏹 <?= e($toyGrubu[0]['toy_adi']) ?> <small><?= e($toyGrubu[0]['sezon_adi']??'') ?></small></h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Yarış</th><th>Kategori</th><th>Sporcu</th><th>İşlem</th></tr></thead><tbody><?php foreach($toyGrubu as $toy): ?><tr><td><?= e($toyTurleri[$toy['yarisma_turu']]??'') ?></td><td><?= e($kategoriler[$toy['kategori']]??$toy['kategori']) ?></td><td><?= (int)$toy['katilimci'] ?></td><td class="actions"><a class="btn btn-sm btn-primary" href="<?= BASE_URL ?>/admin/toy-karsilasmalari.php?toy_id=<?= (int)$toy['id'] ?>">Puan Gir</a><a class="btn btn-sm" href="<?= BASE_URL ?>/admin/toylar.php?islem=duzenle&id=<?= (int)$toy['id'] ?>">Düzenle</a><form method="post" class="inline-form" onsubmit="return confirm('Toy Yarışı ve tüm puanları silinsin mi?')"><?= csrf_field() ?><input type="hidden" name="islem" value="toy_sil"><input type="hidden" name="toy_id" value="<?= (int)$toy['id'] ?>"><button class="btn btn-sm btn-danger">Sil</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php endforeach; ?><?php if(!$liste): ?><p class="muted">Henüz Toy Yarışı oluşturulmadı.</p><?php endif; ?></section></div>
<script>document.addEventListener('DOMContentLoaded',function(){var turler=[].slice.call(document.querySelectorAll('[name="yarisma_turleri[]"]')),kategoriler=[].slice.call(document.querySelectorAll('[name="kategoriler[]"]')),sporcular=[].slice.call(document.querySelectorAll('.toy-sporcu')),arama=document.getElementById('toySporcuAra');function yenile(){var aktifTurler=turler.filter(function(x){return x.checked}).map(function(x){return x.value}),aktifKategoriler=kategoriler.filter(function(x){return x.checked}).map(function(x){return x.value}),metin=(arama.value||'').toLocaleLowerCase('tr');document.querySelectorAll('.toy-ayar').forEach(function(a){a.hidden=!aktifTurler.includes(a.dataset.toyTur)});sporcular.forEach(function(s){var gor=aktifKategoriler.includes(s.dataset.kategori)&&(!metin||s.dataset.arama.includes(metin));s.hidden=!gor;if(!aktifKategoriler.includes(s.dataset.kategori))s.querySelector('input').checked=false;});}turler.concat(kategoriler).forEach(function(x){x.addEventListener('change',yenile)});arama.addEventListener('input',yenile);document.getElementById('toyTumunuSec').addEventListener('click',function(){sporcular.forEach(function(s){if(!s.hidden)s.querySelector('input').checked=true})});document.getElementById('toyTumunuKaldir').addEventListener('click',function(){sporcular.forEach(function(s){if(!s.hidden)s.querySelector('input').checked=false})});yenile();});</script>
